"            {/* Wider Checklist Card (Tägliche Helden-Tasks) since news & lessons are in sidebar */}
            <div className="liquid-glass" style={{ borderRadius: '28px', padding: '32px', marginTop: '20px' }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '8px', color: '#64748b', fontSize: '11px', fontWeight: 900, textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: '20px' }}>
