              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))', gap: '16px' }}>
                {dailyChecklist.map((task) => (
                  <div 
                    key={task.id} 
                    onClick={() => {
                      setDailyChecklist(prev => prev.map(t => t.id === task.id ? { ...t, completed: !t.completed } : t));
                      playGameSound('success');
                    }}
                    style={{
                      padding: '20px 24px',
                      borderRadius: '20px',
                      border: '1.5px solid',
                      borderColor: task.completed ? '#bbf7d0' : '#e2e8f0',
                      background: task.completed ? '#f0fdf4' : '#ffffff',
                      display: 'flex',
                      alignItems: 'center',
                      gap: '14px',
                      cursor: 'pointer',
                      transition: 'all 0.2s',
                      boxShadow: '0 4px 0 #cbd5e1'
                    }}
                  >
                    <span style={{ fontSize: '24px' }}>{task.completed ? '✅' : '⬜'}</span>
                    <span style={{ fontSize: '14px', fontWeight: 800, color: task.completed ? '#047857' : '#1e293b', textDecoration: task.completed ? 'line-through' : 'none' }}>
                      {task.text}
                    </span>
                  </div>
                ))}
              </div>
